":514.6,\"y\":169.5},{\"id\":\"s3\",\"kind\":\"sucht\",\"type\":\"zeit\",\"name\":\"Ferme du Lavoir\",\"place\":\"Bretagne, Frankreich\",\"region\":\"FR\",\"lat\":48.1,\"lon\":-3,\"info\":\"Hof · sucht Volontäre für 2–8 Wochen\",\"need\":\"5 Stunden Mitarbeit am Tag, Kost und Logis frei\",\"since\":\"seit 2014\",\"x\":215.2,\"y\":306},{\"id\":\"s4\",\"kind\":\"sucht\",\"type\":\"coliving\",\"name\":\"Casa Alfama\",\"place\":\"Lissabon, Portugal\",\"region\":\"PT\",\"lat\":38.71,\"lon\":-9.13,\"info\":\"Co-Living · 2 Zimmer frei ab März\",\"need\":\"Mindestens 3 Monate\",\"since\":\"seit 2021\",\"x\":102,\"y\":545.6},{\"id\":\"s5\",\"kind\":\"sucht\",\"type\":\"wohn\",\"name\":\"Wohnprojekt Rheinblick\",\"place\":\"Köln, Deutschland\",\"region\":\"DE\",\"lat\":50.94,\"lon\":6.96,\"info\":\"Bestehendes Wohnprojekt · 1 Wohnung frei\",\"need\":\"Genossenschaftsanteil 12.000 €\",\"since\":\"seit 2012\",\"x\":399.3,\"y\":225.2},{\"id\":\"s6\",\"kind\":\"sucht\",\"type\":\"hof\",\"name\":\"Masía Verde\",\"place\":\"Katalonien, Spanien\",\"region\":\"ES\",\"lat\":41.95,\"lon\":2.3,\"info\":\"Hofgemeinschaft · sucht 1–2 Menschen mit Gartenerfahrung\",\"need\":\"Probejahr\",\"since\":\"seit 2009\",\"x\":313.2,\"y\":467.1},{\"id\":\"s7\",\"kind\":\"sucht\",\"type\":\"spirit\",\"name\":\"Kloster Neuland\",\"place\":\"Bayern, Deutschland\",\"region\":\"DE\",\"lat\":48.9,\"lon\":12.4,\"info\":\"Spirituelle Gemeinschaft · offene Gästewochen\",\"need\":\"Teilnahme an Morgenmeditation\",\"since\":\"seit 1988\",\"x\":499.8,\"y\":283.7}]};\n\n/* ===== ZUSTAND ===== */\nconst S={tier:'gast',mustOrder:[],hist:[],starts:[],duelQ:null,ans:{},order:{},res:null,prev:null,collection:new Set(),selRegions:new Set(['PT','ES']),mode:'beides',fund:'eigen',climate:'egal',showG:true,showS:true,activePin:null};\ntry{JSON.parse(localStorage.getItem('cn_coll')||'[]').forEach(k=>TYPES[k]&&S.collection.add(k))}catch(e){}\nfunction saveColl(){try{localStorage.setItem('cn_coll',JSON.stringify([...S.collection]))}catch(e){}}\nconst $=s=>ROOT.querySelector(s);\nconst esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst RM=window.matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst TIC={};TKEYS.forEach(k=>TIC[k]=iconUrl(TYPES[k].icon));\nconst ico=(k,cls='')=>`<img class=\"ic ${cls}\" src=\"${TIC[k]}\" alt=\"\">`;\n\n\n/* ===== RECHNEN: jede Form einzeln 0–100 % ===== */\nfunction optVals(q,o){\n  if(q.type==='slider')return {kapital:capToAxis(o)};\n  const sel=Array.isArray(o)?o:[o];const tmp={};\n  sel.forEach(i=>{const v=q.o[i].v;for(const a in v)(tmp[a]=tmp[a]||[]).push(v[a])});\n  const r={};for(const a in tmp)r[a]=tmp[a].reduce((x,y)=>x+y,0)/tmp[a].length;return r;\n}\nfunction userVec(ans){\n  const acc={};AXES.forEach(a=>acc[a]=[]);\n  for(const id in ans){const q=id==='duel'?S.duelQ:QIDX[id];if(!q||ans[id]==null)continue;\n    if(Array.isArray(ans[id])&&!ans[id].length)continue;\n    const v=optVals(q,ans[id]);for(const a in v)acc[a].push(v[a])}\n  const u={};AXES.forEach(a=>u[a]=acc[a].length?acc[a].reduce((x,y)=>x+y,0)/acc[a].length:null);u._n={};AXES.forEach(a=>u._n[a]=acc[a].length);return u;\n}\nfunction dist(u,p){let s=0,w=0;AXES.forEach(a=>{if(u[a]==null||p[a]==null)return;s+=WEIGHT[a]*(u[a]-p[a])**2;w+=WEIGHT[a]});return w?Math.sqrt(s/w):1}\nfunction fitPct(u,p){const d=dist(u,p);return Math.max(0,Math.min(100,Math.round(100*(1-(d-.06)/.5))))}\nfunction score(ans){\n  const u=userVec(ans);const pct={};\n  TKEYS.forEach(k=>{let f=fitPct(u,TYPES[k].p);\n    if(k==='spirit'&&(u.spirit==null||u.spirit<.6))f=Math.round(f*.7);\n    pct[k]=f});\n  const rank=TKEYS.slice().sort((a,b)=>pct[b]-pct[a]);\n  const hints=[];\n  for(const id in ans){const q=QIDX[id];const o=ans[id];if(!q||o==null)continue;\n    if(q.type==='slider'){if(o<3000)hints.push('nocap');continue}\n    (Array.isArray(o)?o:[o]).forEach(i=>{if(q.o[i]&&q.o[i].h)hints.push(q.o[i].h)})}\n  if(ans.silence===1&&u.groesse!=null&&u.groesse<.35)hints.push('ritual');\n  return {u,pct,rank,top:rank[0],hints};\n}\nfunction matchPct(u,v){return fitPct(u,v)}\n\n/* ===== KOMPASS ===== */\nfunction buildCompass(el){\n  el.innerHTML=`<div class=\"ring\"></div><div class=\"ring ring2\"></div>`+\n   TKEYS.map((k,i)=>{const ang=i/TKEYS.length*2*Math.PI-Math.PI/2;const x=50+42*Math.cos(ang),y=50+42*Math.sin(ang);\n     return `<div class=\"pt\" data-k=\"${k}\" style=\"left:${x}%;top:${y}%;--c:${TYPES[k].c}\" title=\"${esc(TYPES[k].name)}\">${ico(k)}</div>`}).join('')+\n   '<div class=\"needle\"><svg viewBox=\"0 0 10 100\"><polygon points=\"5,0 10,50 5,46 0,50\" fill=\"#E9AD55\"/><polygon points=\"5,100 10,50 5,54 0,50\" fill=\"rgba(240,230,210,.55)\"/></svg></div><div class=\"hub\"></div>';\n  el._rot=0;\n}\nfunction pointCompass(el,k,extra=0){\n  const target=TKEYS.indexOf(k)/TKEYS.length*360;let cur=el._rot||0;let base=Math.floor(cur/360)*360+target;\n  if(base<cur-180)base+=360;if(base>cur+180)base-=360;base+=extra*360;el._rot=base;\n  el.querySelector('.needle').style.transform=`rotate(${base}deg)`;\n  el.querySelectorAll('.pt').forEach(p=>p.classList.toggle('glow',p.dataset.k===k));\n  if(arguments.length>3)el.querySelectorAll('.pt').forEach(p=>p.classList.toggle('near',p.dataset.k===arguments[3]&&p.dataset.k!==k));\n}\n['#heroCompass','#liveCompass','#revealCompass'].forEach(s=>buildCompass($(s)));\n\n/* ===== ÜBERSICHT ===== */\n$('#typeGrid').innerHTML=TKEYS.map(k=>{const t=TYPES[k];return `\n<article class=\"tcard\" style=\"--c:${t.c}\">\n  <div class=\"ico\">${ico(k)}</div>\n  <h3>${esc(t.name)}</h3>\n  <p class=\"short\">${esc(t.short)}</p>\n  <p class=\"fit\">${esc(t.fit)}</p>\n  <dl class=\"details\" id=\"d-${k}\">\n    <dt>Alltag</dt><dd>${esc(t.alltag)}</dd>\n    <dt>Geld</dt><dd>${esc(t.geld)}</dd>\n    <dt>Eher nichts für dich</dt><dd>${esc(t.nicht[0].toUpperCase()+t.nicht.slice(1))}</dd>\n    <dt>Aus der Forschung</dt><dd>${esc(t.fakt)}<div class=\"src\">Quelle: ${esc(t.src)}</div></dd>\n  </dl>\n  <button class=\"more\" aria-expanded=\"false\" aria-controls=\"d-${k}\">Mehr erfahren</button>\n</article>`}).join('');\nROOT.querySelectorAll('.tcard .more').forEach(b=>b.onclick=()=>{const o=b.closest('.tcard').classList.toggle('open');b.setAttribute('aria-expanded',o);b.textContent=o?'Weniger anzeigen':'Mehr erfahren'});\n$('#toTypes').onclick=()=>$('#types').scrollIntoView({behavior:RM?'auto':'smooth'});\nROOT.querySelectorAll('[data-dead]').forEach(b=>b.onclick=()=>toast('In der Vorschau ist nur „Gemeinschaftsformen“ klickbar'));\n\n\nfunction showOverview(){$('#viewOverview').classList.remove('hidden');$('#viewGame').classList.add('hidden');window.scrollTo(0,0)}\nfunction showGame(part){$('#viewOverview').classList.add('hidden');$('#viewGame').classList.remove('hidden');['quiz','result','match'].forEach(p=>$('#'+p).classList.toggle('hidden',p!==part));window.scrollTo(0,0);sizeFx()}\n\n/* ===== QUIZ: mitdenkende Fragenauswahl ===== */\nlet SEEN=new Set();try{JSON.parse(localStorage.getItem('cn_seen')||'[]').forEach(x=>SEEN.add(x))}catch(e){}\nfunction saveSeen(){try{localStorage.setItem('cn_seen',JSON.stringify([...SEEN]))}catch(e){}}\nfunction shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}\nfunction qAxes(q){if(q.type==='slider')return ['kapital'];const s=new Set();q.o.forEach(o=>Object.keys(o.v).forEach(a=>s.add(a)));return [...s]}\n\n/* Nächste Frage wählen: was der Kompass am wenigsten weiß + was die zwei führenden Formen am besten trennt */\nfunction pickNext(){\n  const asked=new Set(S.hist);const u=userVec(S.ans);const sc=score(S.ans);const A=TYPES[sc.rank[0]].p,B=TYPES[sc.rank[1]].p;\n  const n=S.hist.length;\n  if(n<2)return S.starts[n];\n  if(n===RUN_LEN-1){S.duelQ=duelQuestion(sc.rank[0],sc.rank[1]);return 'duel'}\n  const hintsUsed=S.hist.filter(id=>QIDX[id]&&QIDX[id].k==='hint').length;\n  const kernUsed=S.hist.filter(id=>QIDX[id]&&QIDX[id].k==='kern').length;\n  // Pflichtthemen: Wohnverhältnis (Gruppengröße, eigener Raum), Geld, Ort, Startkapital werden in jedem Durchlauf abgefragt\n  for(const [ax,qid] of S.mustOrder){if(!u._n[ax]&&!asked.has(qid))return qid}\n  // Hinweisfragen fest einstreuen: etwa jede vierte Frage, höchstens HINT_MAX\n  const wantHints=Math.min(HINT_MAX,Math.floor((n-2)/4));\n  if(hintsUsed<wantHints){const hs=shuffle(POOL.filter(q=>q.k==='hint'&&!asked.has(q.id)));if(hs.length)return hs[0].id}\n  let best=null,bestS=-1;\n  POOL.forEach(q=>{\n    if(asked.has(q.id)||q.k==='start')return;\n    if(q.cond&&!q.cond(u,S.ans))return;\n    let s;\n    if(q.k==='hint')return;\n    else{\n      const ax=qAxes(q);if(!ax.length)return;\n      // schon zweimal abgefragte Themen nicht weiter vertiefen\n      if(ax.every(a=>u._n[a]>=2))return;\n      const info=ax.reduce((t,a)=>t+(u._n[a]===0?1:u._n[a]===1?.45:.1),0)/ax.length;\n      const sep=ax.reduce((t,a)=>t+Math.abs(A[a]-B[a])*WEIGHT[a],0)/ax.length;\n      s=info+sep*.9+Math.random()*.6+(SEEN.has(q.id)?0:.25);\n      if(q.k==='kern'&&kernUsed<KERN_TARGET)s+=.55;\n      if(q.k==='zweig')s+=.6;\n    }\n    if(s>bestS){bestS=s;best=q.id}\n  });\n  return best;\n}\nfunction curQ(){const id=S.hist[S.hist.length-1];return id==='duel'?S.duelQ:QIDX[id]}\n\nfunction startQuiz(){\n  S.ans={};S.hist=[];S.duelQ=null;S.order={};S.runStart=Date.now();S.runId=new Date().toISOString().replace(/[:.]/g,'-')+'-'+Math.random().toString(36).slice(2,6);\n  S.starts=shuffle(POOL.filter(q=>q.k==='start').map(q=>q.id)).slice(0,2);\n  S.mustOrder=[...shuffle([['groesse','size'],['privat','space']]),...shuffle([['geld','money'],['land','view'],['kapital','capital']])];\n  $('#liveCompass').querySelectorAll('.pt').forEach(p=>p.classList.remove('glow'));\n  $('#whisper').textContent='Der Kompass hört zu …';showGame('quiz');\n  S.hist.push(pickNext());renderQ();\n}\n$('#startQuiz').onclick=startQuiz;$('#startQuiz2').onclick=startQuiz;\nfunction renderTrail(){\n  const n=S.hist.length;const st=Math.min(4,Math.floor((n-1)/3));\n  $('#trail').innerHTML=STAGES.map((nm,i)=>`<div class=\"stage ${i<st?'done':''} ${i===st?'cur':''}\"><span class=\"dot\"></span>${nm}</div>`).join('');\n  $('#counter').textContent=`${n} / ${RUN_LEN}`;\n}\nconst WHISPERS=['Hm, interessant …','Der Kompass zittert.','Da zeichnet sich was ab …','Noch nicht ganz klar …','Spannend.','Der Kompass dreht sich …','Aha!','Darüber will der Kompass mehr wissen.'];\nfunction renderQ(){\n  renderTrail();const q=curQ();SEEN.add(q.id);saveSeen();\n  if(q.o&&!S.order[q.id])S.order[q.id]=q.k==='duel'?[0,1]:shuffle(q.o.map((_,i)=>i));\n  const kindLabel=q.k==='start'?'Bauchfrage':q.k==='zweig'?'Nur für dich':q.k==='duel'?'Entscheidung':q.th;\n  const head=`<div class=\"qstage\">${esc(kindLabel)}${q.k==='zweig'?' · '+esc(q.th):''}</div><h2 class=\"qtitle\">${esc(q.t)}</h2><p class=\"qtext\">${esc(q.x||(q.k==='start'?'Nicht lange nachdenken.':''))}</p>`;\n  if(q.type==='slider'){\n    const cur=S.ans[q.id]!=null?S.ans[q.id]:10000;const idx=CAP_STEPS.indexOf(cur)>=0?CAP_STEPS.indexOf(cur):6;\n    $('#qcard').innerHTML=`<div class=\"qcard\">${head}<div class=\"sliderbox\">\n      <div class=\"sval\" id=\"sval\">${euro(cur)}</div><div class=\"slabel\" id=\"slabel\">${capLabel(cur)}</div>\n      <input type=\"range\" id=\"cap\" min=\"0\" max=\"${CAP_STEPS.length-1}\" step=\"1\" value=\"${idx}\" aria-label=\"Startkapital in Euro\">\n      <div class=\"sticks\"><span>0 €</span><span>20.000 €</span><span>100.000 €</span><span>200.000 € +</span></div>\n      <div class=\"row\" style=\"justify-content:flex-start;margin-top:24px\"><button class=\"btn gold\" id=\"capOk\">Weiter →</button></div></div></div>`;\n    const r=$('#cap');const upd=()=>{const e=CAP_STEPS[+r.value];$('#sval').textContent=euro(e);$('#slabel').textContent=capLabel(e);r.style.setProperty('--p',(r.value/(CAP_STEPS.length-1)*100)+'%')};\n    upd();r.oninput=()=>{upd();pointCompass($('#liveCompass'),score({...S.ans,[q.id]:CAP_STEPS[+r.value]}).top)};\n    $('#capOk').onclick=()=>commit(CAP_STEPS[+r.value],$('#capOk'));r.focus();return;\n  }\n  const two=q.o.length===2;\n  if(q.multi){\n    const sel=new Set(Array.isArray(S.ans[q.id])?S.ans[q.id]:[]);const max=q.max||99;\n    $('#qcard').innerHTML=`<div class=\"qcard\">${head}<div class=\"opts\">${S.order[q.id].map((oi,n)=>{const o=q.o[oi];return `<button class=\"opt multi ${sel.has(oi)?'sel':''}\" data-oi=\"${oi}\" aria-pressed=\"${sel.has(oi)}\"><span class=\"oe\">${o.e}</span><span class=\"ot\">${esc(o.t)}</span><span class=\"ok\">${n+1}</span><span class=\"tick\">✓</span></button>`}).join('')}</div>\n      <div class=\"row\" style=\"justify-content:flex-start;margin-top:20px\"><button class=\"btn gold\" id=\"multiOk\" ${sel.size?'':'disabled'}>Weiter →</button><span class=\"multihint\"></span></div></div>`;\n    const upd=()=>{$('#multiOk').disabled=!sel.size;ROOT.querySelector('.multihint').textContent=sel.size?(sel.size+' ausgewählt'+(q.max?` von höchstens ${q.max}`:'')):'Wähle mindestens eine Antwort';\n      if(sel.size)pointCompass($('#liveCompass'),score({...S.ans,[q.id]:[...sel]}).top)};\n    upd();\n    ROOT.querySelectorAll('.opt').forEach(b=>b.onclick=()=>{const oi=+b.dataset.oi;\n      if(sel.has(oi))sel.delete(oi);else{if(sel.size>=max){toast(`Höchstens ${max} Antworten`);return}sel.add(oi)}\n      b.classList.toggle('sel',sel.has(oi));b.setAttribute('aria-pressed',sel.has(oi));\n      const r=b.getBoundingClientRect();if(sel.has(oi))burst(r.left+r.width/2,r.top+r.height/2,8,'#E9AD55');upd()});\n    $('#multiOk').onclick=()=>commit([...sel],$('#multiOk'));return;\n  }\n  $('#qcard').innerHTML=`<div class=\"qcard\">${head}<div class=\"opts ${two?'two':''}\">${S.order[q.id].map((oi,n)=>{const o=q.o[oi];return `<button class=\"opt ${two?'big':''} ${S.ans[q.id]===oi?'chosen-before':''}\" data-oi=\"${oi}\"><span class=\"oe\">${o.e}</span><span class=\"ot\">${esc(o.t)}</span><span class=\"ok\">${n+1}</span></button>`}).join('')}</div></div>`;\n  ROOT.querySelectorAll('.opt').forEach(b=>b.onclick=()=>commit(+b.dataset.oi,b));\n}\nlet busy=false;\nfunction commit(val,btn){\n  if(busy)return;busy=true;const q=curQ();S.ans[q.id]=val;\n  if(btn.classList.contains('opt'))btn.classList.add('picked');\n  const r=btn.getBoundingClientRect();burst(r.left+r.width/2,r.top+r.height/2,14,'#E9AD55');\n  const scL=score(S.ans);pointCompass($('#liveCompass'),scL.top,0,scL.rank[1]);\n  $('#whisper').textContent=WHISPERS[Math.floor(Math.random()*WHISPERS.length)];\n  logRun('läuft');\n  setTimeout(()=>{busy=false;\n    if(S.hist.length>=RUN_LEN){finish();return}\n    const nx=pickNext();if(!nx){finish();return}\n    S.hist.push(nx);renderQ()},RM?120:520);\n}\n$('#qBack').onclick=()=>{\n  if(S.hist.length>1){const id=S.hist.pop();delete S.ans[id];const prev=S.hist[S.hist.length-1];\n    // Antwort der vorherigen Frage bleibt sichtbar markiert, wird aber neu gesetzt\n    renderQ()}else showOverview()};\ndocument.addEventListener('keydown',e=>{if(!ROOT.host.isConnected)return;\n  if($('#viewGame').classList.contains('hidden')||$('#quiz').classList.contains('hidden')||!$('#modal').classList.contains('hidden'))return;\n  if(((e.composedPath&&e.composedPath()[0])||e.target).tagName==='INPUT')return;\n  const n=parseInt(e.key,10);const opts=[...ROOT.querySelectorAll('.opt')];if(n>=1&&n<=opts.length)opts[n-1].click();\n  if(e.key==='Enter'&&$('#multiOk')&&!$('#multiOk').disabled){e.preventDefault();$('#multiOk').click()}});\n\n\n/* ===== AUFLÖSUNG ===== */\nfunction finish(){\n  S.prev=null;S.res=score(S.ans);const rv=$('#reveal');rv.classList.remove('hidden');sizeFx();\n  const c=$('#revealCompass'),t=$('#revealText');const lines=['Der Kompass sucht …','Er wägt ab …','Gleich …'];let n=0;t.textContent=lines[0];\n  if(RM){done();return}\n  pointCompass(c,S.res.rank[2],2);\n  const iv=setInterval(()=>{n++;if(n<lines.length)t.textContent=lines[n]},900);\n  setTimeout(()=>pointCompass(c,S.res.rank[1],1),1000);\n  setTimeout(()=>pointCompass(c,S.res.top,1),2000);\n  setTimeout(()=>{clearInterval(iv);t.textContent=TYPES[S.res.top].name+'!';burst(innerWidth/2,innerHeight/2,70,TYPES[S.res.top].c);burst(innerWidth/2,innerHeight/2,50,'#E9AD55')},3100);\n  setTimeout(done,4000);\n  function done(){logRun('fertig');rv.classList.add('hidden');addCollection(S.res.top);renderResult();showGame('result')}\n}\nfunction addCollection(k){const isNew=!S.collection.has(k);S.collection.add(k);saveColl();return isNew}\n\n/* ===== ERGEBNIS ===== */\nfunction barsHTML(res,prev){\n  return `<div class=\"bars\">${res.rank.map((k,i)=>{const t=TYPES[k];const d=prev?res.pct[k]-prev.pct[k]:0;\n   return `<div class=\"bar ${i===0?'top':''}\" style=\"--c:${t.c}\"><span class=\"mini\">${ico(k)}</span><div class=\"bl\">${esc(t.name)}</div><div class=\"track\"><div class=\"fill\" data-w=\"${res.pct[k]}\"></div></div><div class=\"pc\">${res.pct[k]} %${d?`<span class=\"delta ${d>0?'up':'down'}\">${d>0?'+':''}${d}</span>`:''}</div></div>`}).join('')}</div>`}\nfunction animateBars(root,from){root.querySelectorAll('.fill').forEach((f,i)=>{if(from&&from[i]!=null)f.style.width=from[i]+'%';requestAnimationFrame(()=>requestAnimationFrame(()=>f.style.width=f.dataset.w+'%'))})}\nfunction capIdx(){const v=S.ans.capital;const i=CAP_STEPS.indexOf(v);return i<0?6:i}\n\nfunction renderResult(){\n  const r=S.res,t=TYPES[r.top],second=TYPES[r.rank[1]];const gap=r.pct[r.top]-r.pct[r.rank[1]];const hatstall=gap<=3;\n  const badges=[];\n  if(hatstall)badges.push(`Zwei Formen passen fast gleich gut zu dir: ${t.name} und ${second.name}`);\n  else if(r.pct[r.top]>=70)badges.push('🎯 Starke Passung');\n  const multi=r.rank.filter(k=>r.pct[k]>=60);if(multi.length>=3)badges.push(`✨ ${multi.length} Formen passen über 60 %`);\n  let html=`<div class=\"rhero\">\n    <div class=\"pre\">Dein Kompass zeigt auf</div>\n    <div class=\"bigico\" style=\"--c:${t.c}\">${ico(r.top)}</div>\n    <h1 class=\"rname\">${esc(t.name)}</h1>\n    <p class=\"rtag\">${esc(S.tier==='gast'?t.short:t.tag)}</p>\n    ${badges.length&&S.tier!=='gast'?`<div class=\"badges\">${badges.map(b=>`<span class=\"badge\">${esc(b)}</span>`).join('')}</div>`:''}\n  </div>`;\n  if(S.tier==='gast'){\n    html+=`<div class=\"lockbox\"><div class=\"blur\" aria-hidden=\"true\">${barsHTML(r)}</div>\n      <div class=\"lockover\"><h3>Das ist erst die halbe Wahrheit</h3>\n        <p>Mit einem kostenlosen Konto siehst du, wie gut jede der 8 Formen zu dir passt, was dich dort erwartet und worauf du achten solltest. Und du kannst durchspielen, was sich mit mehr Startkapital oder mit deiner Partnerin oder deinem Partner ändert.</p>\n        <button class=\"btn gold\" id=\"toKonto\">Ganzes Ergebnis freischalten</button></div></div>\n    <div class=\"row\"><button class=\"btn ghost\" id=\"again\">🔁 Nochmal spielen</button><button class=\"btn ghost\" id=\"toOv\">Alle Formen ansehen</button></div>`;\n  } else {\n    const hints=[...new Set(r.hints)].map(h=>HINTS[h]);\n    if(r.top==='wohn'&&S.ans.capital!=null&&S.ans.capital<5000)hints.push('Wohnprojekte brauchen oft Kapital. Such gezielt nach Mietmodellen wie dem Mietshäusersyndikat oder nach Genossenschaften.');\n    if(r.u.komfort!=null&&r.u.komfort<.3&&r.u.land!=null&&r.u.land>.7)hints.push('Du willst aufs Land, aber mit vollem Komfort. Dort sind Bäder, Heizung und Sauberkeit oft anders. Schau dir das beim Besuch genau an.');\n    hints.push('Zugehörigkeit kommt nicht sofort. Rechne mit Verliebtheit, dann Ernüchterung, dann echtem Ankommen.');\n    html+=`<div class=\"panels\">\n      <div class=\"panel\">\n        <h3>So gut passt jede Form zu dir</h3>\n        <div id=\"barsWrap\">${barsHTML(r,S.prev)}</div>\n        <p class=\"barnote\">Jede Form wird einzeln bewertet. 100 % hieße: Deine Antworten passen genau zum typischen Profil dieser Form. Es können also auch mehrere Formen gut passen.</p>\n        ${!hatstall?`<div class=\"nearmiss\">Knapp dahinter: <b>${esc(second.name)}</b> mit ${r.pct[r.rank[1]]} %. Spiel rechts durch, was den Kompass kippen lässt.</div>`:''}\n        ${whyHTML(r)}\n        <h4>Was dich erwartet</h4><p>${esc(t.alltag)}</p>\n        <h4>Typischer Irrtum</h4><p>${esc(t.irrtum)}</p>\n        <h4>Darauf solltest du achten</h4><ul>${hints.map(h=>`<li>${esc(h)}</li>`).join('')}</ul>\n        <h4>Frag beim Besuch</h4><p>„Was gefällt dir an dieser Gemeinschaft am wenigsten?“ Wie viele sind in den letzten zwei Jahren gegangen, und warum? Wem gehört das Land?</p>\n      </div>\n      <div style=\"display:grid;gap:18px;align-content:start\">\n        <div class=\"panel\"><h3>Was wäre, wenn …?</h3>\n          <p style=\"margin:-4px 0 14px;font-size:14px;opacity:.8\">Ändere eine Antwort, der Kompass rechnet sofort neu.</p>\n          <div class=\"levers\">${LEVERS.map(L=>{\n            if(L.slider){return `<div class=\"lever\"><label for=\"lcap\">${L.label}: <span class=\"lv\" id=\"lcapv\">${euro(S.ans.capital??10000)}</span></label><input type=\"range\" id=\"lcap\" min=\"0\" max=\"${CAP_STEPS.length-1}\" step=\"1\" value=\"${capIdx()}\" style=\"--p:${capIdx()/(CAP_STEPS.length-1)*100}%\"></div>`}\n            const q=Q.find(x=>x.id===L.id);const curK=S.ans[L.id]!=null?q.o[S.ans[L.id]].k:null;\n            return `<div class=\"lever\"><label>${L.label}</label><div class=\"chips\">${q.o.map((o,oi)=>`<button class=\"chip ${o.k===curK?'on':''}\" data-l=\"${L.id}\" data-oi=\"${oi}\">${esc(L.labels[o.k])}</button>`).join('')}</div></div>`}).join('')}</div>\n        </div>\n        <div class=\"panel\">\n          <div class=\"collhead\"><h3>Deine Sammlung</h3><small>${S.collection.size} / 8 entdeckt</small></div>\n          <div class=\"collection\">${TKEYS.map(k=>`<div class=\"slot ${S.collection.has(k)?'got':''}\" style=\"--c:${TYPES[k].c}\" title=\"${S.collection.has(k)?esc(TYPES[k].name):'Noch nicht entdeckt'}\">${S.collection.has(k)?ico(k):'?'}</div>`).join('')}</div>\n          <p style=\"font-size:13.5px;margin:10px 0 0;color:var(--gold-soft)\">Fragen entdeckt: ${SEEN.size} von ${POOL.length}. Jeder Durchlauf stellt andere Fragen.</p><p style=\"font-size:13.5px;margin:6px 0 0;opacity:.78\">Jede Form, auf die dein Kompass einmal zeigt, landet hier. Welches Leben würde zu dir passen, wenn du ein paar Dinge anders machen würdest?</p>\n          <div class=\"sharecard\"><div class=\"si\" style=\"--c:${t.c}\">${ico(r.top)}</div><div><small>Mein Communet-Kompass</small><b>${r.pct[r.top]} % ${esc(t.name)}</b><small>communet.net · Finde deine Gemeinschaftsform</small></div></div>\n          <div class=\"row\" style=\"justify-content:flex-start;margin-top:12px\"><button class=\"btn ghost\" id=\"copyShare\">Text zum Teilen kopieren</button></div>\n        </div>\n      </div>\n    </div>\n    <div class=\"procard\"><div>\n        <h3>Gleichgesinnte finden <span class=\"protag\">PRO</span></h3>\n        <ul><li>Menschen mit ähnlichem Kompass, die etwas gründen oder einsteigen wollen</li><li>Karte mit Projekten in der Gründung, gefiltert nach deinem Wunschort</li><li>Bestehende Gemeinschaften, die gerade aktiv neue Leute suchen</li></ul></div>\n      <button class=\"btn gold\" id=\"toPro\">${S.tier==='pro'?'Zu den Gleichgesinnten →':'Pro freischalten'}</button></div>\n    <div class=\"row\"><button class=\"btn ghost\" id=\"again\">🔁 Nochmal von vorn</button><button class=\"btn ghost\" id=\"toOv\">Alle Formen ansehen</button></div>`;\n  }\n  $('#result').innerHTML=html;animateBars($('#result'));\n  const g=id=>ROOT.getElementById(id);\n  g('again').onclick=startQuiz;g('toOv').onclick=()=>{showOverview();setTimeout(()=>$('#types').scrollIntoView(),30)};\n  if(g('toKonto'))g('toKonto').onclick=openKonto;\n  if(g('toPro'))g('toPro').onclick=()=>S.tier==='pro'?renderMatch():openPro();\n  if(g('copyRun'))g('copyRun').onclick=async()=>{\n    const lines=['Communet-Quiz – mein Durchlauf','Ergebnis: '+S.res.rank.map(k=>TYPES[k].name+' '+S.res.pct[k]+' %').join(', '),''];\n    S.hist.filter(id=>S.ans[id]!=null).forEach((id,i)=>{const q=id==='duel'?S.duelQ:QIDX[id];lines.push((i+1)+'. '+q.t+' → '+answerText(q,S.ans[id]))});\n    try{await navigator.clipboard.writeText(lines.join('\\n'));toast('Kopiert. Jetzt einfach per Nachricht an Jan schicken.')}catch(e){toast('Kopieren hat nicht geklappt.')}};\n  if(g('copyShare'))g('copyShare').onclick=async()=>{const txt=`Mein Communet-Kompass zeigt auf ${t.name} (${r.pct[r.top]} % Passung). Welche Gemeinschaftsform passt zu dir? communet.net`;\n    try{await navigator.clipboard.writeText(txt);toast('Text kopiert')}catch(e){toast('Kopieren hat nicht geklappt.')}};\n  ROOT.querySelectorAll('.chip[data-l]').forEach(b=>b.onclick=()=>lever(b.dataset.l,+b.dataset.oi));\n  const lc=g('lcap');if(lc){lc.oninput=()=>{g('lcapv').textContent=euro(CAP_STEPS[+lc.value]);lc.style.setProperty('--p',lc.value/(CAP_STEPS.length-1)*100+'%')};lc.onchange=()=>lever('capital',CAP_STEPS[+lc.value])}\n}\nfunction answerText(q,a){if(q.type==='slider')return euro(a);return (Array.isArray(a)?a:[a]).map(i=>q.o[i].t).join(' + ')}\nfunction whyHTML(r){\n  const top=TYPES[r.top].p;const others=TKEYS.filter(k=>k!==r.top);\n  const rows=[];\n  for(const id in S.ans){const q=id==='duel'?S.duelQ:QIDX[id];if(!q||q.k==='hint')continue;const v=optVals(q,S.ans[id]);const ax=Object.keys(v);if(!ax.length)continue;\n    // Beitrag: wie viel näher diese Antwort an der Siegerform liegt als im Schnitt an den anderen Formen\n    const dTop=ax.reduce((t,a)=>t+WEIGHT[a]*(v[a]-top[a])**2,0)/ax.length;\n    const dOth=others.reduce((t,k)=>t+ax.reduce((x,a)=>x+WEIGHT[a]*(v[a]-TYPES[k].p[a])**2,0)/ax.length,0)/others.length;\n    rows.push({q,a:S.ans[id],c:dOth-dTop})}\n  rows.sort((x,y)=>y.c-x.c);\n  const pro=rows.filter(x=>x.c>0).slice(0,3),con=rows.filter(x=>x.c<0).slice(-2).reverse();\n  const li=x=>`<li><b>${esc(answerText(x.q,x.a))}</b><br><span style=\"opacity:.7;font-size:13.5px\">${esc(x.q.t)}</span></li>`;\n  const all=S.hist.filter(id=>S.ans[id]!=null).map(id=>{const q=id==='duel'?S.duelQ:QIDX[id];return `<li><span style=\"opacity:.7\">${esc(q.t)}</span><br><b>${esc(answerText(q,S.ans[id]))}</b></li>`}).join('');\n  return `<h4>Warum ${esc(TYPES[r.top].name)}?</h4>\n    ${pro.length?`<p style=\"margin:0 0 4px\">Am stärksten dafür sprachen:</p><ul>${pro.map(li).join('')}</ul>`:''}\n    ${con.length?`<p style=\"margin:12px 0 4px\">Eher dagegen sprach:</p><ul>${con.map(li).join('')}</ul>`:''}\n    <div class=\"row\" style=\"justify-content:flex-start;margin-top:14px\"><button class=\"btn ghost\" id=\"copyRun\">Meine Antworten kopieren, um sie Jan zu schicken</button></div>\n    ${all?`<details style=\"margin-top:12px\"><summary style=\"cursor:pointer;color:var(--gold-soft)\">Alle deine Antworten ansehen (${S.hist.filter(id=>S.ans[id]!=null).length})</summary><ol style=\"display:grid;gap:8px;margin-top:10px\">${all}</ol></details>`:''}`;\n}\nfunction lever(qid,val){\n  if(S.ans[qid]===val)return;\n  const before=S.res,oldTop=before.top;S.ans[qid]=val;S.prev=before;S.res=score(S.ans);\n  logRun('was-wäre-wenn');const isNew=addCollection(S.res.top);const y=window.scrollY;renderResult();window.scrollTo(0,y);\n  animateBars($('#result'),S.res.rank.map(k=>before.pct[k]));\n  if(S.res.top!==oldTop){const t=TYPES[S.res.top];burst(innerWidth/2,200,50,'#E9AD55');\n    toast(isNew?`Neue Form entdeckt: ${t.name}`:`Der Kompass kippt: ${t.name}`);\n    if(isNew){const s=ROOT.querySelectorAll('.slot')[TKEYS.indexOf(S.res.top)];s&&s.classList.add('new')}}\n}\n\n/* ===== KONTO / PRO ===== */\nfunction openModal(html){$('#mbox').innerHTML=html;$('#modal').classList.remove('hidden');const f=$('#mbox').querySelector('input,.btn');f&&f.focus()}\nfunction closeModal(){$('#modal').classList.add('hidden')}\n$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});\ndocument.addEventListener('keydown',e=>{if(!ROOT.host.isConnected)return;if(e.key==='Escape')closeModal()});\nfunction openKonto(){\n  openModal(`<button class=\"x\" aria-label=\"Schließen\" id=\"mx\">×</button><h3>Dein ganzes Ergebnis wartet</h3>\n  <p>Kostenloses Konto anlegen, dann siehst du sofort alles. Dein Quiz geht nicht verloren.</p>\n  <form id=\"kform\"><label for=\"kname\">Vorname</label><input id=\"kname\" autocomplete=\"given-name\" placeholder=\"z. B. Lola\" required>\n  <label for=\"kmail\">E-Mail</label><input id=\"kmail\" type=\"email\" autocomplete=\"email\" placeholder=\"du@beispiel.de\" required>\n  <button class=\"btn gold\" type=\"submit\">Konto anlegen und Ergebnis ansehen</button></form>\n  <div class=\"tiny\">Vorschau: Es wird nichts gespeichert oder versendet.</div>`);\n  $('#mx').onclick=closeModal;\n  $('#kform').onsubmit=e=>{e.preventDefault();closeModal();setTier('konto');toast('Willkommen bei Communet! Hier ist dein ganzes Ergebnis.');burst(innerWidth/2,180,50,'#E9AD55')};\n}\nfunction openPro(){\n  if(S.tier==='gast'){openKonto();return}\n  openModal(`<button class=\"x\" aria-label=\"Schließen\" id=\"mx\">×</button><h3>Communet Pro</h3>\n  <p>Finde Menschen, die das Gleiche vorhaben wie du, und Orte, die gerade jemanden wie dich suchen.</p>\n  <ul class=\"perks\"><li>🤝 Gleichgesinnte mit Übereinstimmung in Prozent</li><li>🗺️ Karte mit Projekten in der Gründung</li><li>📣 Gemeinschaften, die aktiv suchen</li><li>💬 Direktnachrichten</li></ul>\n  <button class=\"btn gold\" id=\"proGo\">In der Beta frei: Pro freischalten</button>\n  <div class=\"tiny\">Preis nach der Beta noch offen. Vorschau: Es wird nichts gebucht.</div>`);\n  $('#mx').onclick=closeModal;$('#proGo').onclick=()=>{closeModal();setTier('pro');renderMatch()};\n}\nfunction setTier(t){\n  S.tier=t;ROOT.querySelectorAll('.seg button').forEach(b=>b.classList.toggle('on',b.dataset.tier===t));\n  if(!S.res)return;\n  if(!$('#match').classList.contains('hidden')&&t!=='pro'){renderResult();showGame('result');return}\n  if(!$('#result').classList.contains('hidden'))renderResult();\n}\nROOT.querySelectorAll('.seg button').forEach(b=>b.onclick=()=>{\n  const t=b.dataset.tier;\n  if(!S.res&&t!=='gast'){\n    S.ans={S4:1,S1:1,who:1,morning:[1,2],space:1,money:1,capital:30000,view:2,decide:3,purpose:[0,5],goats:0,simple:2,learn:[0,1],VG1:0,eco:2,duel:1};S.duelQ=duelQuestion('oeko','hof');\n    S.res=score(S.ans);addCollection(S.res.top);S.tier=t;\n    ROOT.querySelectorAll('.seg button').forEach(x=>x.classList.toggle('on',x.dataset.tier===t));\n    if(t==='pro')renderMatch();else{renderResult();showGame('result')}\n    toast('Beispiel-Ergebnis geladen. Spiel das Quiz für dein eigenes.');return}\n  setTier(t)});\n\n/* ===== GLEICHGESINNTE ===== */\nfunction renderMatch(){\n  const r=S.res;const pinsVis=MAP.pins.filter(p=>p.kind==='gruendung'?S.showG:S.showS);\n  $('#match').innerHTML=`\n    <button class=\"backbtn\" id=\"mBack\">← Zurück zum Ergebnis</button>\n    <h2 class=\"goldline\" style=\"margin-top:18px\">Deine Gleichgesinnten</h2>\n    <p class=\"sub\">Dein Kompass zeigt auf ${esc(TYPES[r.top].name)}. Sag uns, wo du das machen willst, dann zeigen wir dir Menschen und Orte, die passen.</p>\n    <div class=\"wo panel\">\n      <div class=\"lever\"><label>🗺️ Wo möchtest du das machen? (mehrere möglich)</label><div class=\"chips\">${Object.entries(REGIONS).map(([k,n])=>`<button class=\"chip ${S.selRegions.has(k)?'on':''}\" data-reg=\"${k}\">${n}</button>`).join('')}<button class=\"chip ${S.selRegions.size===0?'on':''}\" data-reg=\"all\">Egal wo</button></div></div>\n      <div class=\"lever\"><label>🌤️ Welches Klima wünschst du dir?</label><div class=\"chips\">${[['warm','Das ganze Jahr warm'],['vier','Alle vier Jahreszeiten'],['egal','Egal']].map(([k,n])=>`<button class=\"chip ${S.climate===k?'on':''}\" data-clim=\"${k}\">${n}</button>`).join('')}</div>\n        ${S.climate==='warm'&&['hof','oeko'].includes(r.top)?`<p class=\"warnnote\">Warme Regionen haben oft wenig Wasser oder magere Böden. Wer Landwirtschaft betreiben will, sollte sich Wasser und Boden vor Ort genau ansehen.</p>`:''}</div>\n      <div class=\"lever\"><label>💶 Willst du mit deinem Kapital auch andere mitfinanzieren?</label><div class=\"chips\">${[['eigen','Nur meinen eigenen Anteil'],['helfen','Anderen den Einstieg erleichtern (Darlehen, Raten)'],['projekt','Ein ganzes Projekt finanzieren']].map(([k,n])=>`<button class=\"chip ${S.fund===k?'on':''}\" data-fund=\"${k}\">${n}</button>`).join('')}</div>\n        ${S.fund==='projekt'?`<p class=\"warnnote\">Gehört das Land einer einzelnen Person, entsteht leicht ein Machtgefälle. Die Literatur nennt das „Lehnsherr und Leibeigene“. Plane von Anfang an, wie andere sich schrittweise einkaufen können, zum Beispiel über eine Genossenschaft oder das Mietshäusersyndikat.</p>`:''}</div>\n      <div class=\"lever\"><label>🧭 Was hast du vor?</label><div class=\"chips\">${[['gruenden','Selbst gründen'],['einsteigen','Irgendwo einsteigen'],['beides','Beides offen']].map(([k,n])=>`<button class=\"chip ${S.mode===k?'on':''}\" data-mode=\"${k}\">${n}</button>`).join('')}</div></div>\n    </div>\n    <div class=\"mapgrid\"><div>\n      <div class=\"mapbox\"><span class=\"examplenote\">BEISPIELDATEN</span>\n        <svg viewBox=\"0 0 ${MAP.W} ${MAP.H}\" role=\"img\" aria-label=\"Karte Europa mit Projekten\">\n          ${MAP.countries.map(c=>{const reg=Object.keys(REGION_IDS).find(k=>REGION_IDS[k]===c.id);return `<path class=\"country ${reg&&S.selRegions.has(reg)?'sel':''}\" d=\"${c.d}\"><title>${esc(c.n)}</title></path>`}).join('')}\n          ${pinsVis.map(p=>{const t=TYPES[p.type];const fade=(S.selRegions.size&&!S.selRegions.has(p.region))||(S.mode==='gruenden'&&p.kind!=='gruendung')||(S.mode==='einsteigen'&&p.kind!=='sucht');\n            return `<g class=\"pin ${fade?'faded':''} ${S.activePin===p.id?'act':''}\" data-pin=\"${p.id}\" tabindex=\"0\" role=\"button\" aria-label=\"${esc(p.name)}\">${p.kind==='gruendung'?`<circle class=\"halo\" cx=\"${p.x}\" cy=\"${p.y}\" r=\"11\" stroke=\"#E9AD55\"/>`:''}<circle class=\"core\" cx=\"${p.x}\" cy=\"${p.y}\" r=\"11\" fill=\"${t.c}\"/><image href=\"${TIC[p.type]}\" x=\"${p.x-7}\" y=\"${p.y-7}\" width=\"14\" height=\"14\"/></g>`}).join('')}\n        </svg>\n        <div class=\"legend\"><span><i class=\"lg-ring\"></i>Projekt in Gründung</span><span><i class=\"lg-dot\"></i>Gemeinschaft sucht Leute</span></div>\n      </div>\n      <div class=\"chips\" style=\"margin-top:10px\"><button class=\"chip ${S.showG?'on':''}\" id=\"tG\">Gründungsprojekte</button><button class=\"chip ${S.showS?'on':''}\" id=\"tS\">Suchende Gemeinschaften</button></div>\n    </div>\n    <div style=\"display:grid;gap:16px;align-content:start\">\n      <div class=\"panel pindetail\" id=\"pinDetail\"><div class=\"k\">Tippe auf einen Punkt</div><p style=\"margin:8px 0 0\">Pulsierende Punkte sind Projekte in der Gründung, ruhige Punkte bestehende Gemeinschaften, die gerade jemanden suchen. Das Icon zeigt die Form.</p></div>\n      <div class=\"panel\"><h3>Menschen mit ähnlichem Kompass</h3>\n        <div class=\"people\">${PEOPLE.map(p=>({...p,m:matchPct(r.u,p.v)})).filter(p=>!S.selRegions.size||S.selRegions.has(p.reg)).sort((a,b)=>b.m-a.m).map(p=>`\n          <div class=\"person\"><div class=\"avatar\">${esc(p.n[0])}</div><div><b>${esc(p.n)}, ${p.a}</b><small>${esc(p.plan)} · ${esc(p.cap)}</small><button class=\"minibtn\" data-contact>Kontakt anfragen</button></div><div class=\"mpc\">${p.m} %<small>ähnlich</small></div></div>`).join('')||'<p>In dieser Region noch niemand. Wähle mehr Länder aus.</p>'}</div>\n        <p style=\"font-size:12.5px;opacity:.65;margin:12px 0 0\">Beispielpersonen. Später sichtbar nur, wer zugestimmt hat. Gezeigt werden nur das Ergebnis und der Plan, nicht die einzelnen Antworten.</p>\n      </div></div></div>`;\n  showGame('match');\n  $('#mBack').onclick=()=>{renderResult();showGame('result')};\n  ROOT.querySelectorAll('[data-reg]').forEach(b=>b.onclick=()=>{const k=b.dataset.reg;if(k==='all')S.selRegions.clear();else S.selRegions.has(k)?S.selRegions.delete(k):S.selRegions.add(k);rerenderMatch()});\n  ROOT.querySelectorAll('[data-clim]').forEach(b=>b.onclick=()=>{S.climate=b.dataset.clim;rerenderMatch()});\n  ROOT.querySelectorAll('[data-fund]').forEach(b=>b.onclick=()=>{S.fund=b.dataset.fund;rerenderMatch()});\n  ROOT.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{S.mode=b.dataset.mode;rerenderMatch()});\n  $('#tG').onclick=()=>{S.showG=!S.showG;rerenderMatch()};$('#tS').onclick=()=>{S.showS=!S.showS;rerenderMatch()};\n  ROOT.querySelectorAll('.pin').forEach(g=>{const f=()=>showPin(g.dataset.pin);g.addEventListener('click',f);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();f()}})});\n  ROOT.querySelectorAll('[data-contact]').forEach(b=>b.onclick=()=>toast('In der Vorschau nicht aktiv.'));\n  if(S.activePin)showPin(S.activePin);\n}\nfunction rerenderMatch(){const y=window.scrollY;renderMatch();window.scrollTo(0,y)}\nfunction showPin(id){\n  const p=MAP.pins.find(x=>x.id===id);if(!p)return;S.activePin=id;const t=TYPES[p.type];\n  ROOT.querySelectorAll('.pin').forEach(g=>g.classList.toggle('act',g.dataset.pin===id));\n  $('#pinDetail').innerHTML=`<div class=\"k\">${p.kind==='gruendung'?'Projekt in Gründung':'Gemeinschaft sucht Leute'} · ${esc(t.name)}</div>\n   <h3>${esc(p.name)}</h3><p style=\"margin:0;opacity:.8\">${esc(p.place)}</p>\n   <p style=\"margin:10px 0 4px\">${esc(p.info)}</p><p style=\"margin:0;font-size:14px;opacity:.85\">${esc(p.need)} · ${esc(p.since)}</p>\n   ${S.res?`<p style=\"margin:10px 0 0;color:var(--gold-soft);font-size:14px\">Diese Form passt zu ${S.res.pct[p.type]} % zu dir.</p>`:''}\n   <button class=\"minibtn\" id=\"pinSave\" style=\"margin-top:10px\">Projekt merken</button>`;\n  $('#pinSave').onclick=()=>toast('Gemerkt (nur in der Vorschau)');\n}\n\n/* Testprotokoll: fertige Durchläufe in Supabase (Tabelle quiz_runs, nur Einfügen, kein Lesen von außen) */\nconst SB_URL='https://dgffntczrhwujjtvbytj.supabase.co',SB_KEY='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImRnZmZudGN6cmh3dWpqdHZieXRqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODUxMjU2NjgsImV4cCI6MjEwMDcwMTY2OH0.p1XSBHbShlTGwi8YYuZhniiZJxTDVgUQWOxkPNfPPNM';\nlet whatIfCount=0;\nfunction logRun(stage){\n  if(stage!=='fertig'&&stage!=='was-wäre-wenn')return;\n  if(stage==='fertig')whatIfCount=0;else if(++whatIfCount>10)return;\n  try{\n    const sc=score(S.ans);const u=sc.u;const ax={};AXES.forEach(a=>{if(u[a]!=null)ax[a]=Math.round(u[a]*100)/100});\n    const player=((ROOT.getElementById('player')||{}).value||'').trim().slice(0,40)||null;\n    const data={tier:S.tier,antworten:S.hist.filter(id=>S.ans[id]!=null).map(id=>{const q=id==='duel'?S.duelQ:QIDX[id];return {id,art:q.k,frage:q.t,antwort:answerText(q,S.ans[id])}}),\n      ergebnis:sc.rank.map(k=>({form:TYPES[k].name,prozent:sc.pct[k]})),themen:ax,hinweise:[...new Set(sc.hints)]};\n    fetch(SB_URL+'/rest/v1/quiz_runs',{method:'POST',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY,'Content-Type':'application/json',Prefer:'return=minimal'},\n      body:JSON.stringify({run_id:S.runId,player,stage:stage==='fertig'?'fertig':'was-waere-wenn',data})}).catch(()=>{});\n  }catch(e){}\n}\n/* ===== HINWEIS + PARTIKEL ===== */\nlet tt;function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(tt);tt=setTimeout(()=>t.classList.remove('show'),2600)}\nconst fx=$('#fx'),ctx=fx.getContext('2d');let parts=[],stars=[];\nfunction sizeFx(){fx.width=innerWidth*devicePixelRatio;fx.height=innerHeight*devicePixelRatio;\n  stars=Array.from({length:70},()=>({x:Math.random()*fx.width,y:Math.random()*fx.height,r:Math.random()*1.4+.3,p:Math.random()*6.28}))}\naddEventListener('resize',sizeFx);\nfunction burst(x,y,n,col){if(RM)return;for(let i=0;i<n;i++){const a=Math.random()*6.28,s=(Math.random()*5+2)*devicePixelRatio;parts.push({x:x*devicePixelRatio,y:y*devicePixelRatio,vx:Math.cos(a)*s,vy:Math.sin(a)*s-2,l:1,c:Math.random()<.5?col:'#F3CF94',r:(Math.random()*2.5+1)*devicePixelRatio})}}\nfunction loop(t){if(!ROOT.host.isConnected)return;\n  const rvOn=!$('#reveal').classList.contains('hidden');fx.style.zIndex=rvOn?70:1;\n  if(!$('#viewGame').classList.contains('hidden')||rvOn){\n    ctx.clearRect(0,0,fx.width,fx.height);\n    stars.forEach(s=>{ctx.globalAlpha=.25+.25*Math.sin(t/900+s.p);ctx.fillStyle='#F3CF94';ctx.beginPath();ctx.arc(s.x,s.y,s.r*devicePixelRatio,0,6.28);ctx.fill()});\n    parts=parts.filter(p=>p.l>0);parts.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.12*devicePixelRatio;p.vx*=.98;p.l-=.018;ctx.globalAlpha=Math.max(p.l,0);ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,6.28);ctx.fill()});\n    ctx.globalAlpha=1}\n  requestAnimationFrame(loop)}\nrequestAnimationFrame(loop);\n";
